		StringBuilder label = new StringBuilder();
		for (String part : parts) {
			if (part.isEmpty()) {
				continue;
			}
			if (label.length() > 0) {
				label.append(' ');
			}
			label.append(Character.toUpperCase(part.charAt(0)));
			if (part.length() > 1) {
				label.append(part.substring(1));
			}
		}
		return label.length() == 0 ? value : label.toString();
